create table if not exists faults(id uuid primary key default gen_random_uuid(),tenant_id uuid references tenants(id) on delete cascade,channel_id uuid references channels(id) on delete cascade,project_id uuid references projects(id) on delete cascade,job_id uuid references automation_jobs(id) on delete cascade,type text not null,component text,root_cause text,message text not null,status text not null default 'active',attempts int not null default 0,metadata jsonb not null default '{}',created_at timestamptz not null default now(),resolved_at timestamptz);
create table if not exists recovery_attempts(id uuid primary key default gen_random_uuid(),fault_id uuid not null references faults(id) on delete cascade,action text not null,status text not null,details jsonb not null default '{}',created_at timestamptz not null default now());
